using System.Security.Claims;using MaintenancePRO.Api.Contracts;using MaintenancePRO.Api.Data;using MaintenancePRO.Api.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace MaintenancePRO.Api.Controllers;
[ApiController,Route("api/interventions"),Authorize]
public sealed class InterventionsController(AppDbContext db,Microsoft.AspNetCore.Identity.UserManager<ApplicationUser> users):ControllerBase{
[HttpGet] public async Task<IActionResult> List([FromQuery]InterventionStatus? status){var q=db.Interventions.AsNoTracking().AsQueryable();var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);if(User.IsInRole(AppRoles.Technician))q=q.Where(x=>x.AssignedTechnicianId==uid);else if(User.IsInRole(AppRoles.User))q=q.Where(x=>x.CreatedByUserId==uid);if(status.HasValue)q=q.Where(x=>x.Status==status);return Ok(await q.OrderByDescending(x=>x.CreatedUtc).ToListAsync());}
[HttpGet("{id:int}")] public async Task<IActionResult> Get(int id){var x=await db.Interventions.AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id);if(x==null)return NotFound();if(!CanRead(x))return Forbid();return Ok(x);}
[HttpPost] public async Task<IActionResult> Create(CreateInterventionRequest r){if(!await db.Equipments.AnyAsync(x=>x.Code==r.EquipmentCode))return BadRequest(new{message="Équipement inconnu."});var x=new MaintenanceIntervention{Title=r.Title.Trim(),Description=r.Description.Trim(),EquipmentCode=r.EquipmentCode.Trim(),CreatedByUserId=User.FindFirstValue(ClaimTypes.NameIdentifier)!,Status=InterventionStatus.Submitted};db.Interventions.Add(x);db.AuditEvents.Add(new AuditEvent{ActorUserId=x.CreatedByUserId,Action="InterventionCreated",EntityType="Intervention"});await db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.Id},x);}
[HttpPatch("{id:int}"),Authorize(Policy="WorkInterventions")] public async Task<IActionResult> Update(int id,UpdateInterventionRequest r){var x=await db.Interventions.FindAsync(id);if(x==null)return NotFound();var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);if(User.IsInRole(AppRoles.Technician)&&x.AssignedTechnicianId!=uid)return Forbid();if(r.AssignedTechnicianId!=null){if(!User.IsInRole(AppRoles.Admin)&&!User.IsInRole(AppRoles.Supervisor))return Forbid();var tech=await users.FindByIdAsync(r.AssignedTechnicianId);if(tech==null||tech.Status!=AccountStatus.Active||!await users.IsInRoleAsync(tech,AppRoles.Technician))return BadRequest(new{message="Technicien actif invalide."});x.AssignedTechnicianId=tech.Id;}
var allowed=r.Status switch{InterventionStatus.Approved or InterventionStatus.Rejected or InterventionStatus.Assigned or InterventionStatus.Closed=>User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor),InterventionStatus.InProgress=>x.Status is InterventionStatus.Assigned or InterventionStatus.Approved or InterventionStatus.InProgress,InterventionStatus.Completed=>x.Status==InterventionStatus.InProgress,InterventionStatus.Cancelled=>x.Status==InterventionStatus.Submitted&&x.CreatedByUserId==uid,_=>false};if(!allowed)return Conflict(new{message="Transition de statut non autorisée."});x.Status=r.Status;if(r.Resolution!=null){if(r.Resolution.Length>2000)return BadRequest(new{message="Résolution trop longue."});x.Resolution=r.Resolution.Trim();}if(r.Status==InterventionStatus.Completed)x.CompletedUtc=DateTime.UtcNow;db.AuditEvents.Add(new AuditEvent{ActorUserId=uid,Action="InterventionStatusChanged",EntityType="Intervention",EntityId=id.ToString(),IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()});await db.SaveChangesAsync();return Ok(x);}
private bool CanRead(MaintenanceIntervention x){var uid=User.FindFirstValue(ClaimTypes.NameIdentifier);return User.IsInRole(AppRoles.Admin)||User.IsInRole(AppRoles.Supervisor)||x.CreatedByUserId==uid||(User.IsInRole(AppRoles.Technician)&&x.AssignedTechnicianId==uid);}}
